// currency and image_url fall back to what is stored rather than blanking the
// column, and game_name is only written when the payload carried one. `claimed`
// is written unconditionally because the only path that sets it true is an
// explicit upstream "this token is claimed", and defaulting it to false here
// would resurrect a claimed token on the next re-scrape.
func (q *Queries) UpdateTokenTransfer(ctx context.Context, arg UpdateTokenTransferParams) (MarketplaceTokenTransfer, error) {
	row := q.db.QueryRowContext(ctx, updateTokenTransfer,
		arg.TokenID,
		arg.GameName,
		arg.SellerID,
		arg.BuyerID,
		arg.ItemName,
		arg.Price,
		arg.Currency,
		arg.ImageUrl,
		arg.CreatedAt,
		arg.Claimed,
		arg.TxHash,
	)
	var i MarketplaceTokenTransfer
	err := row.Scan(
		&i.ID,
		&i.TokenID,
		&i.GameName,
		&i.SellerID,
		&i.BuyerID,
		&i.ItemName,
		&i.Price,
		&i.Currency,
		&i.TxHash,
		&i.ImageUrl,
		&i.CreatedAt,
		&i.Claimed,
	)
	return i, err
}

const updateUserUsername = `-- name: UpdateUserUsername :exec
UPDATE users SET username = $2 WHERE id = $1
`

type UpdateUserUsernameParams struct {
	ID       string         `json:"id"`
	Username sql.NullString `json:"username"`
}

func (q *Queries) UpdateUserUsername(ctx context.Context, arg UpdateUserUsernameParams) error {
	_, err := q.db.ExecContext(ctx, updateUserUsername, arg.ID, arg.Username)
	return err
}
